<!doctype html>
<html lang="bn"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Wishlist | FREEDelivery.com</title><link rel="stylesheet" href="style.css?v=11"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"></head><body><main class="about-page"><a href="index.php" class="modal-btn" style="display:inline-block;width:auto"><i class="fa-solid fa-arrow-left"></i> হোমে ফিরুন</a><section class="about-card"><h1><i class="fa-solid fa-heart" style="color:#ec4899"></i> আমার Wishlist</h1><div id="wishlistPage"></div></section></main><script>const box=document.getElementById('wishlistPage');let items=[];try{items=JSON.parse(localStorage.getItem('freedelivery_wishlist')||'[]')}catch(e){};box.innerHTML=items.length?items.map(item=>`<article class="wishlist-row"><img src="${String(item.image||'https://placehold.co/80x80?text=Product').replace(/"/g,'&quot;')}" alt=""><div><strong>${String(item.name||'').replace(/[&<>]/g,'')}</strong><small>৳ ${Number(item.price||0).toLocaleString('en-US')}</small></div></article>`).join(''):'<p class="empty-state">Wishlist এখনো খালি।</p>';</script></body></html>
